## Why This Is Asked

Tests the ability to design pluggable runtime components with hot-swapping capabilities, focusing on minimal interfaces, a registry, and safe switching in production.

## Key Concepts

- Strategy pattern
- Registry/Plugin architecture
- Concurrency-safe state management
- Observability and metrics
- Hot-reload without downtime

## Code Example

```typescript
export interface ThrottlingStrategy {
  tryAcquire(tokens: number, ctx?: any): boolean;
  name: string;
}

export class Registry {
  private factories = new Map<string, () => ThrottlingStrategy>();
  register(name: string, factory: () => ThrottlingStrategy) { this.factories.set(name, factory); }
  create(name: string): ThrottlingStrategy { const f = this.factories.get(name); return f ? f() : new (class Default implements ThrottlingStrategy { name = 'default'; tryAcquire() { return true; } })(); }
}

export class ThrottlingManager {
  private strategy?: ThrottlingStrategy;
  constructor(private registry: Registry) {}
  configure(name: string) { this.strategy = this.registry.create(name); }
  permit(tokens: number, ctx?: any): boolean { return this.strategy?.tryAcquire(tokens, ctx) ?? true; }
}
```

